 "content": "def transform(grid):
    """Reduce each 3x3 tile to its first non-background marker (0 and 5 are background)."""
    height, width = len(grid), len(grid[0])
    output = []
    for r0 in range(0, height, 3):
        row = []
        for c0 in range(0, width, 3):
            markers = [
                grid[r][c]
                for r in range(r0, min(r0 + 3, height))
                for c in range(c0, min(c0 + 3, width))
                if grid[r][c] not in (0, 5)
            ]
            row.append(markers[0] if markers else 0)
        output.append(row)
    return output
